 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color, texture, fract, sin } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = config.name || 'features-card-2-label';

  const visualSpec = config.intent?.visualSpec ?? {};
  const visualColors = visualSpec.colors ?? config.colors ?? {};

  const ink = new Color(visualColors.ink ?? '#16161d');
  const surface = new Color(visualColors.surface ?? '#0b0b10');
  const paper = new Color(visualColors.paper ?? '#e8ecf2');
  const accent = new Color(visualColors.accent ?? '#ff2a38');

  const aspect = 512 / 320;
  const height = 0.72;
  const width = height * aspect;
  const geometry = new PlaneGeometry(width, height);

  const u = uv();

  const gradient = mix(
    color(ink.getHex()),
    color(surface.getHex()),
    smoothstep(0.0, 1.0, u.y)
  );

  const accentBand = smoothstep(0.0, 0.08, u.y).mul(0.65);
  const gradientWithAccent = mix(gradient, color(accent.getHex()), accentBand);

  const grain = fract(
    sin(u.x.mul(1234.5).add(u.y.mul(7890.6))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.03);

  const baseColor = gradientWithAccent.add(vec3(grain));

  const material = new MeshBasicNodeMaterial();
  material.colorNode = baseColor;

  const plane = new Mesh(geometry, material);
  plane.position.z = -0.02;
  group.add(plane);

  const textItems = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of textItems) {
    if (item.text) {
      const label = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 39,
        color: '#' + paper.getHexString(),
        align: 'center'
      });
      label.position.z = 0.02;
      group.add(label);
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      const texNode = texture(tex, uv());
      material.colorNode = mix(baseColor, texNode.rgb, texNode.a.mul(0.35));
      material.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData.handlers = {};
  group.userData.timelines = [];
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
